export const PAINT_SIZE=512;
const DATA={"knife/standard":["",""],"short-sword/standard":["",""],"sword/standard":["",""],"axe/standard":["",""],"pick/standard":["",""],"blacksmith-hammer/standard":["",""],"mace/standard":["",""],"spear/standard":["",""],"halberd/standard":["",""],"bow/standard":["",""],"crossbow/standard":["",""],"round-wood-shield/standard":["",""],"round-wood-shield/teal":["",""],"emblem-metal-shield/standard":["",""],"emblem-metal-shield/red":["",""],"tower-shield/standard":["",""],"riot-shield/standard":["",""],"riot-shield/opaque":["",""]};
function base64(text){const chars='ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/',out=new Uint8Array(text.length*3/4);let n=0,bits=0,k=0;for(const c of text){if(c==='=')break;n=n<<6|chars.indexOf(c);bits+=6;if(bits>=8){bits-=8;out[k++]=n>>bits&255;}}return out.subarray(0,k);}
export function equipmentPaintPixels(id,finish='standard'){const entry=DATA[id+'/'+finish];if(!entry)throw Error('EQUIPMENT_PAINT: unknown skin '+id+'/'+finish);const palette=base64(entry[0]),stream=base64(entry[1]),indices=new Uint8Array(512*512);let i=0,k=0;while(i<stream.length){const token=stream[i++];if(token<128){const count=token+1;indices.set(stream.subarray(i,i+count),k);i+=count;k+=count;}else{const count=(token&127)+4,offset=stream[i++]|stream[i++]<<8;for(let n=0;n<count;n++){indices[k]=indices[k-offset];k++;}}}if(k!==indices.length)throw Error('EQUIPMENT_PAINT: invalid decoded length');const pixels=new Uint8Array(512*512*4);for(let n=0;n<indices.length;n++)pixels.set(palette.subarray(indices[n]*4,indices[n]*4+4),n*4);return pixels;}
